const raw = $input.first().json.output;

// Strip markdown code fences
const stripped = raw.replace(/^```json\n/, '').replace(/\n```$/, '');

// Parse the outer JSON
const content = JSON.parse(stripped);
if (content.error) {
  return [{
    json: {
      ...content,
    },
  }];
}

const fullObj = $('Parse Webhook').first().json;
// Content is a process definition
if (content.id) {
  fullObj['process_definition'] = content;
  fullObj['process_id'] = content.id;
}

return [{
  json: {
    ...fullObj,
    responde: false,
  },
}];

const body = $input.first().json.body;
return [{
  json: {
    ...body,
    github_owner: 'blasvicco',
    github_repo: 'da-sapot-processes',
  },
}];

const { language, message } = $('Parse Webhook').first().json
const chatInput = `
The following tool error occurred while processing a user request:

Error: ${$json.error}
User message: ${message}

Write a short, friendly message to the user explaining that something 
went wrong, what it was roughly about, and that they can try again 
or contact support. Do not use technical jargon.
Use user language to reply: ${language}

Make sure the response is a valid json with the next format:
\`\`\`json
{
  "error": "AGENT_ERROR",
  "message": "Your message to the user",
  "responde": true
}
\`\`\`
`;

return [{
  json: {
    chatInput,
  }
}];
